#include <stdio.h>
#include <string.h>
#include <stdlib.h>
int cmp(const void *a, const void *b) { return (*(char*)a - *(char*)b); }
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    char words[100][50], sorted[100][50];
    for (int i = 0; i < n; i++) {
        scanf("%s", words[i]);
        strcpy(sorted[i], words[i]);
        qsort(sorted[i], strlen(sorted[i]), 1, cmp);
    }
    int printed[100] = {0};
    for (int i = 0; i < n; i++) {
        if (printed[i]) continue;
        printf("%s", words[i]); printed[i] = 1;
        for (int j = i + 1; j < n; j++) {
            if (!printed[j] && strcmp(sorted[i], sorted[j]) == 0) {
                printf(" %s", words[j]); printed[j] = 1;
            }
        }
        putchar('\n');
    }
    return 0;
}

