#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
#include <algorithm>
using namespace std;
int main() {
    int n; if (cin >> n) {
        unordered_map<string, vector<string>> groups;
        vector<string> order;
        for (int i = 0; i < n; i++) {
            string w; cin >> w;
            string k = w; sort(k.begin(), k.end());
            if (groups.find(k) == groups.end()) order.push_back(k);
            groups[k].push_back(w);
        }
        for (const string &k : order) {
            for (size_t i = 0; i < groups[k].size(); i++) {
                if (i > 0) cout << " ";
                cout << groups[k][i];
            }
            cout << "\n";
        }
    }
    return 0;
}

code.Java:
import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            LinkedHashMap<String, List<String>> groups = new LinkedHashMap<>();
            for (int i = 0; i < n; i++) {
                String w = sc.next();
                char[] ca = w.toCharArray(); Arrays.sort(ca);
                String k = new String(ca);
                groups.computeIfAbsent(k, x -> new ArrayList<>()).add(w);
            }
            for (List<String> g : groups.values()) {
                System.out.println(String.join(" ", g));
            }
        }
    }
}

