import sys
from collections import defaultdict
def main():
    toks = sys.stdin.read().split()
    if toks:
        n = int(toks[0])
        words = toks[1:1+n]
        groups = defaultdict(list)
        for w in words:
            k = "".join(sorted(w))
            groups[k].append(w)
        for g in groups.values():
            print(" ".join(g))
