const fs = require("fs");
function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/);
    if (toks.length > 0) {
        const n = parseInt(toks[0], 10);
        const words = toks.slice(1, 1 + n);
        const map = new Map();
        for (const w of words) {
            const k = w.split("").sort().join("");
            if (!map.has(k)) map.set(k, []);
            map.get(k).push(w);
        }
        for (const g of map.values()) console.log(g.join(" "));
    }
}
main();

